    $set = $variant === 'solid' ? $solid : $outline;
    $d = $set[$name] ?? $outline[$name] ?? $outline['sparkles'];

    // Several icons are multi-subpath (e.g. "signal", "map-pin"). Heroicons
    // ships them as one `d`, but keeping them in a single outline path makes
    // the stroke connector join the subpaths into a visible diagonal artefact.
    // Split on uppercase "M" so each subpath is stroked independently.
    $segments = preg_split('/(?=M)/', trim($d), -1, PREG_SPLIT_NO_EMPTY) ?: [$d];
    $paths = array_values(array_filter(array_map('trim', $segments), fn ($s) => $s !== ''));

    $dimension = $size ?: '1.25rem';

    $classes = 'shrink-0 ' . ($attributes->get('class') ?? '');
