<svg
    {{ $attributes->except('class')->merge(['class' => $classes]) }}
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    width="{{ $dimension }}"
    height="{{ $dimension }}"
    @if($variant === 'solid')
        fill="currentColor"
        {{-- even-odd so counter-shapes knock out of their parent shape. Heroicons
             solid glyphs happen to be wound correctly already, but brand marks
             like `whatsapp` rely on it to cut the handset out of the bubble. --}}
        fill-rule="evenodd"
        clip-rule="evenodd"
        aria-hidden="true"
    @else
        fill="none"
        stroke="currentColor"
        stroke-width="{{ $strokeWidth }}"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
    @endif
>
    @foreach($paths as $segment)
        <path d="{{ $segment }}" />
    @endforeach
</svg>
